        self.Mpipi_GGv1 = nmds.fit_transform(self.Mpipi_GGv1)
        self.Mpipi_GGv1 = self.Mpipi_GGv1/ (abs(-self.Mpipi_GGv1.min() + self.Mpipi_GGv1.max()) + 0.1)



