class MSA_data_class(Father_OnlyForSetConstantAttribute):
    def __init__(self,*, pars_args_MSA_data_folder, pars_args_MSA_data_name, pars_args_sequence_RowDashCount_threshold=0.5):
        self.set_attribute_constants()
        self.pars_args_MSA_data_folder = pars_args_MSA_data_folder
        self.MSA_data_path = pars_args_MSA_data_folder + pars_args_MSA_data_name
        self.sequence_RowDashCount_threshold = pars_args_sequence_RowDashCount_threshold

    def compute_weight(self, seq, seq_list, d0=0.01, eta=1):
        number_non_empty_positions = np.dot(seq, seq)
        if number_non_empty_positions > 0:
            similarities = np.dot(seq_list, seq.T) / number_non_empty_positions
            similar_enough_cnt = np.sum(similarities > 1 - d0)
            return float(similar_enough_cnt) ** (-eta)
        else:
            return 0.0

    def compute_weights(self, use_weights=1, d0=0.01, eta=1):
        if not hasattr(self, 'OneHotEncoding_np'):
            self.compute_OneHotEncoding_ForTrain()
        if use_weights:
            print ("Start to compute sequence weights")
            start_time = time.time()
            OneHotEncoding_np = self.OneHotEncoding_np
            OneHotEncoding_np = OneHotEncoding_np.reshape((OneHotEncoding_np.shape[0], OneHotEncoding_np.shape[1] * OneHotEncoding_np.shape[2]))
            myfunc = lambda x: self.compute_weight(x, OneHotEncoding_np, d0=d0, eta=eta)
            self.weights = np.array( [myfunc(x) for x in tqdm(OneHotEncoding_np)] )
            print("Computing sequence weights finished with " + str(time.time() - start_time) + " seconds.")
        else:
            self.weights = np.ones(self.OneHotEncoding_np.shape[0])

    def compute_muts_2_aa_str(self, muts, aa_str, position_ini):
        # ONLY for 'all'. not for 'rbd'
        if muts == 'B0B':
            this_aa_str = aa_str
        else:
            muts_list = muts.split(',')
            pre_i       = position_ini - 1
            this_aa_str = ''
            for this_mut in muts_list:
                if this_mut[:3] == "ins" or this_mut[-1] in ['B', 'J', 'O', 'U', 'X', 'Z']:
                        continue
                this_i       = int(this_mut[1:-1]) - 1
                this_aa_str += aa_str[pre_i: this_i]
                if aa_str[int(this_mut[1:-1]) - 1] != this_mut[0]:
                    raise ValueError("please check: 2 AAs are different, when comparing AA-sequence and mutations description ")
                this_aa_str += this_mut[-1]
                pre_i        = this_i + 1
            this_aa_str += aa_str[pre_i: 1273]
        return this_aa_str

    def compute_OneHotEncoding_NamedByOneHotAndChemicalEncoding_ForTrain(self):
        if not hasattr(self, 'cleaned_sequence_np'):
            self.set_cleaned_original_msa_data()
        OneHotEncoding_np = np.zeros((len(self.cleaned_sequence_np), len(self.cleaned_sequence_np[0]), len(self.alphabet)))
        if not hasattr(self, 'alphabet'):
            self.set_attribute_constants()
        # One-Hot Encoding with Chemical info
        for i, aa_str in enumerate(self.cleaned_sequence_np):
            for j,aa_letter in enumerate(aa_str):
                aa_letter = aa_letter.upper()
                if aa_letter in self.alphabet_set:
                    k = self.AA_2_OneHotIndex_dict[aa_letter]
                    OneHotEncoding_np[i, j, k]  = 1.0
        self.OneHotEncoding_np = OneHotEncoding_np
        self.OneHotAndChemicalEncoding_np = OneHotEncoding_np

    def compute_OneHotAndChemicalEncoding_ForTrain(self):
        if not hasattr(self, 'cleaned_sequence_np'):
            self.set_cleaned_original_msa_data()
        aa_str_len = len(self.cleaned_sequence_np[0])
        OneHotAndChemicalEncoding_np = np.zeros((len(self.cleaned_sequence_np), aa_str_len, len(self.alphabet) + 6))
        if not hasattr(self, 'alphabet'):
            self.set_attribute_constants()
        # One-Hot Encoding with Chemical info
        for i, aa_str in enumerate(self.cleaned_sequence_np):
            aa_str = aa_str.upper()
            for j,aa_letter in enumerate(aa_str):
                if aa_letter in self.alphabet_set:
                    k = self.AA_2_OneHotIndex_dict[aa_letter]
                    OneHotAndChemicalEncoding_np[i, j, k]  = 1.0
                    OneHotAndChemicalEncoding_np[i, j, -4] = self.AA_2_polarity_dict[aa_letter]
                    OneHotAndChemicalEncoding_np[i, j, -3] = self.AA_2_SideChainMass_dict[aa_letter]
                    OneHotAndChemicalEncoding_np[i, j, -2] = self.AA_2_charge_dict[aa_letter]
                    OneHotAndChemicalEncoding_np[i, j, -1] = self.AA_2_EisenbergWeissHydrophobicity_dict[aa_letter]
                    if aa_letter=='N' and aa_str_len > j+2 and aa_str[j+2] in {'S', 'T'} and aa_str[j+1] != 'P':
                        OneHotAndChemicalEncoding_np[i, j:j+3, -5]  = 1.0
            for O_AA, O_Site in self.potential_O_site:
                if O_AA==aa_str[O_Site]:
                    OneHotAndChemicalEncoding_np[i, j, -6]  = 1.0
        self.OneHotAndChemicalEncoding_np = OneHotAndChemicalEncoding_np


    def compute_OneHotAndChemicalEncodingAndFF_ForTrain(self):
        if not hasattr(self, 'cleaned_sequence_np'):
            self.set_cleaned_original_msa_data()
        aa_str_len = len(self.cleaned_sequence_np[0])
        OneHotAndChemicalEncoding_np = np.zeros((len(self.cleaned_sequence_np), aa_str_len, len(self.alphabet) + 6 + self.Mpipi_dim))
        if not hasattr(self, 'alphabet'):
            self.set_attribute_constants()
        # One-Hot Encoding with Chemical info
        for i, aa_str in enumerate(self.cleaned_sequence_np):
            aa_str = aa_str.upper()
            for j,aa_letter in enumerate(aa_str):
                if aa_letter in self.alphabet_set:
                    k = self.AA_2_OneHotIndex_dict[aa_letter]
                    OneHotAndChemicalEncoding_np[i, j, k]  = 1.0
                    OneHotAndChemicalEncoding_np[i, j, 20:20 + self.Mpipi_dim]  = self.Mpipi_GGv1[k]
                    OneHotAndChemicalEncoding_np[i, j, -4] = self.AA_2_polarity_dict[aa_letter]
                    OneHotAndChemicalEncoding_np[i, j, -3] = self.AA_2_SideChainMass_dict[aa_letter]
                    OneHotAndChemicalEncoding_np[i, j, -2] = self.AA_2_charge_dict[aa_letter]
                    OneHotAndChemicalEncoding_np[i, j, -1] = self.AA_2_EisenbergWeissHydrophobicity_dict[aa_letter]
                    if aa_letter=='N' and aa_str_len > j+2 and aa_str[j+2] in {'S', 'T'} and aa_str[j+1] != 'P':
                        OneHotAndChemicalEncoding_np[i, j:j+3, -5]  = 1.0
            for O_AA, O_Site in self.potential_O_site:
                if O_AA==aa_str[O_Site]:
                    OneHotAndChemicalEncoding_np[i, j, -6]  = 1.0
        self.OneHotAndChemicalEncoding_np = OneHotAndChemicalEncoding_np

    def compute_OneHotEncoding_ForTrain(self):
        if not hasattr(self, 'cleaned_sequence_np'):
            self.set_cleaned_original_msa_data()
        OneHotEncoding_np = np.zeros((len(self.cleaned_sequence_np), len(self.cleaned_sequence_np[0]), len(self.alphabet)))
        if not hasattr(self, 'alphabet'):
            self.set_attribute_constants()
        # One-Hot Encoding with Chemical info
        for i, aa_str in enumerate(self.cleaned_sequence_np):
            for j,aa_letter in enumerate(aa_str):
                aa_letter = aa_letter.upper()
                if aa_letter in self.alphabet_set:
                    k = self.AA_2_OneHotIndex_dict[aa_letter]
                    OneHotEncoding_np[i, j, k]  = 1.0
        self.OneHotEncoding_np = OneHotEncoding_np


    def set_cleaned_original_msa_data(self, sequence_ColDashCount_threshold=1.0):
        sequence_RowDashCount_threshold = self.sequence_RowDashCount_threshold
        if not hasattr(self, 'ori_sequence_list'):
            self.set_read_a2m_file()
        if sequence_ColDashCount_threshold<1.0:
            raise ValueError('graph structure does not support columns selection now!!! please set sequence_ColDashCount_threshold=1.0')
            # ColDashCount_list = [s.count('-') for s in self.ori_sequence_OriColIndex_list]
        RowDashCount_np = np.array([s.count('-') for s in self.ori_sequence_list])
        RowDashCount_threshold = sequence_RowDashCount_threshold * self.ori_sequence_OriColIndex_list.__len__()
        RowDashCount_remained_ind = RowDashCount_np < RowDashCount_threshold

        self.cleaned_sequence_np               = np.array(self.ori_sequence_list)[RowDashCount_remained_ind]
        self.cleaned_sequence_name_np          = np.array(self.ori_sequence_name_list)[RowDashCount_remained_ind]
        self.cleaned_sequence_OriColIndex_list = [''.join(seq_list) for seq_list in zip(*self.cleaned_sequence_np)]

    def add_new_df_to_cleaned_sequence_np(self, new_pd):

        new_pd['aa_str'] = new_pd['mutations'].apply(self.compute_muts_2_aa_str, args=(self.P0DTC2, 1, )) 
        new_aa_str_np  = new_pd['aa_str'].values
        self.cleaned_sequence_np = np.concatenate((self.cleaned_sequence_np, new_aa_str_np), axis=0)


    def set_read_a2m_file(self, file_path=''):
        if len(file_path) == 0:
            file_path = self.MSA_data_path

        sequence_list      = []
        sequence_name_list = []

        with open(file_path, 'r') as file:
            for line in file:
                if line.startswith('#') or not line.strip():
                    continue
                if line.startswith('>'):
                    sequence_name = line.strip().replace('>', '')
                    sequence_name_list.append(sequence_name)
                    continue
                sequence_list.append(line.strip())

        sequence_colindex_list = [''.join(seq_list) for seq_list in zip(*sequence_list)]  # 将序列比对转置，使每个序列成为一行

        self.ori_sequence_list             = sequence_list
        self.ori_sequence_name_list        = sequence_name_list
        self.ori_sequence_OriColIndex_list = sequence_colindex_list



