    def is_AA_min_nuc_dis_dict_1(self, xlist):
        for x_str in xlist:
            x_sublist = x_str.split('+')
            x = x_sublist[1]
            y = x[0] + x[-1]
            if y in self.AA_min_nuc_dis_dict:
                if self.AA_min_nuc_dis_dict[y] < 2:
                    return True
            else:
                print(x + ' is illegal')
        return False

    def compute_only_position_dict(self, pre_index):
        res = {}
        pre_index_only_position = [indx.split(',') for indx in pre_index]
        for val_list_ind, val_list in enumerate(pre_index_only_position):
            new_val_list = []
            for val in val_list:
                new_val_list.append(val[1:-1])
            pre_index_only_position[val_list_ind] = ','.join(new_val_list)
            res[pre_index_only_position[val_list_ind]] = pre_index[val_list_ind]
        return res, pre_index_only_position

    def compute_mut_2_aa_str(self, mut_str, aa_str, position_ini):
        i   = int(mut_str[1:-1]) - position_ini
        res = aa_str[:i]
        if aa_str[i] != mut_str[0]:
            raise ValueError("please check: 2 AAs different, when comparing AA-sequence and mutations description ")
        return res + mut_str[-1] + aa_str[i+1:]

    def compute_aa_str_2_whole_mutations(self, aa_str, ref_str, position_ini):
        res_list = [ref_str[i] + str(i + position_ini) + aa_str[i] for i in range(len(ref_str)) if aa_str[i] != ref_str[i] ]
        if res_list.__len__()==0:
            res_list = ['B0B']
        return ','.join(res_list)

    def set_structure_by_PDBParser(self, pdb_file = './data/PDB/6vxx.pdb'):

        p = PDBParser(PERMISSIVE=1)
        structure = p.get_structure("pdb_6vxx", pdb_file)
        sasa_result, sasa_classes = freesasa.calcBioPDB(structure)
        sasa_residueAreas_dict    = sasa_result.residueAreas()
        sasa_residueAreas_dict_attribute_name_list = ['total', 'mainChain', 'sideChain', 'polar', 'apolar', 'hasRelativeAreas',
         'relativeTotal', 'relativeMainChain', 'relativeSideChain', 'relativePolar', 'relativeApolar']
        aa_name_list     = []
        aa_position_list = []
        aa_ChainId_list  = []
        aa_CACoord_list  = []
        aa_SideChainMeanCoord_list = []
        aa_residueAreas_list       = []
        for i, residue in enumerate(structure.get_residues()):
            if not is_aa(residue):
                # print('Not aa, dropped')
                continue
            if residue.get_id()[2].strip() != '':
                print('Please check: Insert happened!! This insert will be omitted!!')
                continue
            aa_name_list.append(self.protein_letters_3to1_dict[residue.resname])
            aa_position_list.append(int(residue.get_id()[1]))
            aa_ChainId_list.append(residue.get_full_id()[2])
            this_sasa_res = sasa_residueAreas_dict[residue.get_full_id()[2]][str(residue.get_id()[1])]
            aa_residueAreas_list.append({key: getattr(this_sasa_res, key) for key in sasa_residueAreas_dict_attribute_name_list})
            aa_SideChainMeanCoord_this = np.zeros(3)
            aa_SideChain_cnt           = 0
            for atom in residue:
                if atom.name == 'CA':  # alpha-carbon
                    aa_CACoord_list.append(atom.get_coord())
                    continue
                if atom.name in ['C', 'O', 'N']:  # These are in the main chain, not side chain
                    continue
                aa_SideChainMeanCoord_this += atom.get_coord()
                aa_SideChain_cnt           += 1

            if aa_SideChain_cnt:
                aa_SideChainMeanCoord_list.append(aa_SideChainMeanCoord_this/aa_SideChain_cnt)
            else:
                aa_SideChainMeanCoord_list.append(aa_CACoord_list[-1])
                if aa_name_list[-1] != 'G':
                    print('Please check: Side chain is replaced by alpha-carbon, which happened not when aa is Gly(G)')

        self.structure_pd_dict = {pdb_file[pdb_file.rfind('/')+1:-4]: pd.DataFrame(
                                        {   'aa_name': aa_name_list,
                                            'aa_position': aa_position_list,
                                            'aa_ChainId': aa_ChainId_list,
                                            'aa_CACoord': aa_CACoord_list,
                                            'aa_SideChainMeanCoord': aa_SideChainMeanCoord_list,
                                            'aa_residueAreas': aa_residueAreas_list
                                        })
                                  }
        
    def get_SASA(self, *, all_OR_rbd_str='all', pdb_file='./data/PDB/6vxx.pdb', SASA_key_list=['total', 'sideChain', 'relativeTotal', 'relativeSideChain'], SASA_and_WCN_para_dict=0):
        
        if type(SASA_and_WCN_para_dict) == int:
            SASA_lower_bound = 0.1
            SASA_upper_bound = 5.0
            SASA_unknown_structure_fill_val     = 2.0
            SASA_unknown_structure_fill_percent = 0.7
            SASA_std_lower_bound = 0.000001
            SASA_std_upper_bound = 0.1
        else:
            SASA_lower_bound = SASA_and_WCN_para_dict['lower_bound']
            SASA_upper_bound = SASA_and_WCN_para_dict['upper_bound']
            SASA_unknown_structure_fill_val     = SASA_and_WCN_para_dict['unknown_structure_fill_val']
            SASA_unknown_structure_fill_percent = SASA_and_WCN_para_dict['unknown_structure_fill_percent']
            SASA_std_lower_bound = SASA_and_WCN_para_dict['std_lower_bound']
            SASA_std_upper_bound = SASA_and_WCN_para_dict['std_upper_bound']

        if not hasattr(self, 'P0DTC2'):
            self.set_attribute_constants()
        pdb_key = pdb_file[pdb_file.rfind('/') + 1:-4]
        if not (hasattr(self, 'structure_pd_dict') and pdb_key in self.structure_pd_dict.keys()):
            self.set_structure_by_PDBParser(pdb_file=pdb_file)
        structure_pd = self.structure_pd_dict[pdb_key]

        if all_OR_rbd_str == 'all':
            filename_prefix = 'all_'
            position_num    = 1273
            position_ini    = 1
        elif all_OR_rbd_str == 'rbd':
            filename_prefix = 'rbd_331_531_'
            position_num    = 201
            position_ini    = 331
        else:
            raise ValueError("please set: all_OR_rbd_str = 'all' or 'rbd'")

        if not all(x in list(structure_pd.loc[0, 'aa_residueAreas'].keys()) for x in SASA_key_list):
            raise ValueError("please set: SASA_key_list as a sublist of ['total', 'mainChain', 'sideChain', 'polar', 'apolar', 'hasRelativeAreas',\
                             'relativeTotal', 'relativeMainChain', 'relativeSideChain', 'relativePolar', 'relativeApolar']")
        X = np.zeros((position_num * 3, len(SASA_key_list))) # SideChainMeanCoord: geometric mean position of side chain
        Y = np.zeros((position_num * 3, len(SASA_key_list)))
        for i in range(position_num):
            aa_position = i + position_ini
            aa_SideChainCoord_ABC = structure_pd[structure_pd['aa_position']==aa_position]['aa_residueAreas'].values
            if aa_SideChainCoord_ABC.__len__() >=3:
                for j, keyj in enumerate(SASA_key_list):
                    X[3 * i, j]     = aa_SideChainCoord_ABC[0][keyj]
                    X[3 * i + 1, j] = aa_SideChainCoord_ABC[1][keyj]
                    X[3 * i + 2, j] = aa_SideChainCoord_ABC[2][keyj]
            elif aa_SideChainCoord_ABC.__len__() >0:
                for x_chain_id, chain_id in enumerate(['A', 'B', 'C']):
                    aa_SideChainCoord_ABC = structure_pd[(structure_pd['aa_position'] == aa_position) & (structure_pd['aa_ChainId'] == chain_id)]['aa_SideChainMeanCoord'].values
                    if aa_SideChainCoord_ABC.__len__() > 0:
                        for j, keyj in enumerate(SASA_key_list):
                            X[3 * i + x_chain_id, j] = aa_SideChainCoord_ABC[0][keyj]
        for j, keyj in enumerate(SASA_key_list):
            Yj = X[X[:, j]>0, j]
            Yj.sort()
            Y_fill = Yj[int(Yj.__len__() * SASA_unknown_structure_fill_percent)]
            X[~(X[:, j] > 0), j] = Y_fill
            # X[:, j] = 10 * (X[:, j] - Y[0])/ (Y[-1]-Y[0]) # map X[:, j] to from 0 to 10
            # X[:, j] = np.exp( 3 * (X[:, j] - Y[0]) / (Y[-1] - Y[0]) )  # map X[:, j] to from 1 to 20 (exp(3)) or 54 (exp(4))
            X[:, j]   = np.exp( 10.0 * (X[:, j] - Y_fill)/ (Y[-1]-Y_fill) )
            X[:, j][X[:, j]==1.0] = SASA_unknown_structure_fill_val
            X[:, j]   = np.clip(X[:, j], SASA_lower_bound, SASA_upper_bound)
            Y[:, j]   = (SASA_std_upper_bound-SASA_std_lower_bound) * ( X[:, j]-np.min(X[:, j]) ) / ( np.max(X[:, j])-np.min(X[:, j]) ) + SASA_std_lower_bound

        return X, Y


    def set_graph_edge(self, *, all_OR_rbd_str, pdb_file='./data/PDB/6vxx.pdb', SASA_and_WCN_para_dict=0):

        if type(SASA_and_WCN_para_dict) == int:
            WCN_lower_bound = 0.1
            WCN_upper_bound = 5.0
            WCN_unknown_structure_fill_val    = 2.0
            WCN_unknown_structure_fill_percent = 0.7
            WCN_std_lower_bound = 0.000001
            WCN_std_upper_bound = 0.4
        else:
            WCN_lower_bound = SASA_and_WCN_para_dict['lower_bound']
            WCN_upper_bound = SASA_and_WCN_para_dict['upper_bound']
            WCN_unknown_structure_fill_val     = SASA_and_WCN_para_dict['unknown_structure_fill_val']
            WCN_unknown_structure_fill_percent = SASA_and_WCN_para_dict['unknown_structure_fill_percent']
            WCN_std_lower_bound = SASA_and_WCN_para_dict['std_lower_bound']
            WCN_std_upper_bound = SASA_and_WCN_para_dict['std_upper_bound']


        if not hasattr(self, 'P0DTC2'):
            self.set_attribute_constants()
        pdb_key = pdb_file[pdb_file.rfind('/') + 1:-4]
        if not (hasattr(self, 'structure_pd_dict') and pdb_key in self.structure_pd_dict.keys()):
            self.set_structure_by_PDBParser(pdb_file=pdb_file)
        structure_pd = self.structure_pd_dict[pdb_key]

        if all_OR_rbd_str == 'all':
            filename_prefix = 'all_'
            position_num    = 1273
            position_ini    = 1
            euclidean_distance_matrix_threshold = 7.0
            euclidean_distance_matrix_normalization_upperbound = 10.0
        elif all_OR_rbd_str == 'rbd':
            filename_prefix = 'rbd_331_531_'
            position_num    = 201
            position_ini    = 331
            euclidean_distance_matrix_threshold = 7.0
            euclidean_distance_matrix_normalization_upperbound = 10.0
        else:
            raise ValueError("please set: all_OR_rbd_str = 'all' or 'rbd'")

        X = np.zeros((position_num * 3, 3)) # SideChainMeanCoord: geometric mean position of side chain
        for i in range(position_num):
            aa_position = i + position_ini
            aa_SideChainCoord_ABC = structure_pd[structure_pd['aa_position']==aa_position]['aa_SideChainMeanCoord'].values
            if aa_SideChainCoord_ABC.__len__() >=3:
                X[3 * i, :]     = aa_SideChainCoord_ABC[0]
                X[3 * i + 1, :] = aa_SideChainCoord_ABC[1]
                X[3 * i + 2, :] = aa_SideChainCoord_ABC[2]
            else:
                for x_chain_id, chain_id in enumerate(['A', 'B', 'C']):
                    aa_SideChainCoord_ABC = structure_pd[(structure_pd['aa_position'] == aa_position) & (structure_pd['aa_ChainId'] == chain_id)]['aa_SideChainMeanCoord'].values
                    if aa_SideChainCoord_ABC.__len__() > 0:
                        X[3 * i + x_chain_id, :] = aa_SideChainCoord_ABC[0]
        euclidean_distance_matrix = np.sqrt(np.sum(X** 2, axis = 1)[:, np.newaxis] + np.sum(X**2, axis = 1) - 2 * X.dot(X.T))
        for i in range(len(X)):
            if ((i // 3) + position_ini) not in structure_pd['aa_position'].values:  # This is under this observation: For each chain, the positions without coordinates are totally the same! (But why ...)
                euclidean_distance_matrix[i, :] = 1000.0
                euclidean_distance_matrix[:, i] = 1000.0
                euclidean_distance_matrix[i, i] = 0.0

        WCN_matrix = euclidean_distance_matrix.copy()
        mask = euclidean_distance_matrix > 0
        mask_values = 1/(euclidean_distance_matrix[mask] ** 2)
        WCN_matrix[mask] = mask_values
        WCN_list = -np.sum(WCN_matrix, axis=1)

        Y = WCN_list[WCN_list < WCN_list[0]]
        Y.sort()
        Y_fill = Y[int(Y.__len__() * WCN_unknown_structure_fill_percent)]
        WCN_list[~(WCN_list < WCN_list[0])] = Y_fill
        # X[:, j] = 10 * (X[:, j] - Y[0])/ (Y[-1]-Y[0]) # map X[:, j] to from 0 to 10
        # X[:, j] = np.exp( 3 * (X[:, j] - Y[0]) / (Y[-1] - Y[0]) )  # map X[:, j] to from 1 to 20 (exp(3)) or 54 (exp(4))
        WCN_list = np.exp(3 * (WCN_list - Y_fill) / (Y[-1] - Y_fill))
        WCN_list[WCN_list==1.0] = WCN_unknown_structure_fill_val
        WCN_list = np.clip(WCN_list, WCN_lower_bound, WCN_upper_bound)
        WCN_std_list = (WCN_std_upper_bound-WCN_std_lower_bound) * ( WCN_list-np.min(WCN_list) ) / ( np.max(WCN_list)-np.min(WCN_list) ) + WCN_std_lower_bound

        # These commended codes are for deciding euclidean_distance_matrix_threshold by eyes...

        # min_dist_list = []
        # for i in range(position_num * 3):
        #     if not (X[i] == 0).all():
        #         arr = euclidean_distance_matrix[i, :]
        #         min_dist_list.append(min(arr[arr != 0]))
        # plt.hist(min_dist_list)
        # less_than_threshold_counts = np.sum(euclidean_distance_matrix < 7, axis=1)
        # plt.hist(less_than_threshold_counts)

        edge_weight_matrix = euclidean_distance_matrix.copy()
        mask = (euclidean_distance_matrix < euclidean_distance_matrix_threshold) & (euclidean_distance_matrix > 0)
        mask_values = -euclidean_distance_matrix[mask]
        mask_values = (mask_values + euclidean_distance_matrix_normalization_upperbound) / euclidean_distance_matrix_normalization_upperbound
        edge_weight_matrix[mask] = mask_values
        edge_weight_matrix[euclidean_distance_matrix >= euclidean_distance_matrix_threshold] = 0.0

        mainchain_connect_matrix = np.zeros((position_num * 3, position_num * 3)) # For CACoord: alpha-carbon coordinate
        i = 0
        mainchain_connect_matrix[3 * i, 3 * i + 3] = 1
        mainchain_connect_matrix[3 * i + 1, 3 * i + 3 + 1] = 1
        mainchain_connect_matrix[3 * i + 2, 3 * i + 3 + 2] = 1
        for i in range(1, position_num-1):
            mainchain_connect_matrix[3 * i, 3 * i + 3]     = 1
            mainchain_connect_matrix[3 * i+1, 3 * i + 3+1] = 1
            mainchain_connect_matrix[3 * i+2, 3 * i + 3+2] = 1

            mainchain_connect_matrix[3 * i, 3 * i - 3]     = 1
            mainchain_connect_matrix[3 * i+1, 3 * i - 3+1] = 1
            mainchain_connect_matrix[3 * i+2, 3 * i - 3+2] = 1
        i = position_num-1
        mainchain_connect_matrix[3 * i, 3 * i - 3] = 1
        mainchain_connect_matrix[3 * i + 1, 3 * i - 3 + 1] = 1
        mainchain_connect_matrix[3 * i + 2, 3 * i - 3 + 2] = 1

        edge_weight_matrix += mainchain_connect_matrix
        # Previous matrix ranges from 0 to 2; The following step makes all >1 val to =1
        edge_weight_matrix[edge_weight_matrix>1.0] = 1.0

        self.edge_index_j_list = []
        self.edge_index_i_list = []
        self.edge_weight_list  = []
        for i in range(1, position_num * 3):
            for j in range(i):
                if edge_weight_matrix[i, j] > 0:
                    self.edge_index_j_list.append(j)
                    self.edge_index_i_list.append(i)
                    self.edge_weight_list.append(edge_weight_matrix[i, j])
        self.edge_weight_matrix        = edge_weight_matrix
        self.VertexSideChainMean_coord = X
        self.WCN_list = WCN_list
        self.WCN_std_list = WCN_std_list
        
        # plt.hist(edge_weight)
        # print('aaa')

