                # rowi_nptime_list  = [strtime_2_nptime(rowi_strtime_list[i] )for i in range(rowi_strtime_list.__len__())]
                rowi_nptime_list  = [(strtime_2_nptime(rowi_strtime_list[i] ), id_list[i]) for i in range(rowi_strtime_list.__len__())]
                rowi_nptime_cnt   = Counter(rowi_nptime_list)
