    def generate_LeadingWHOVOC_based_1mut_sets(self, *, all_OR_rbd_str, dataframe_all_saved=1, set_attribute=0):

        if not hasattr(self, all_OR_rbd_str + '_mutations_2_WHO_label_dict'):
            self.set_leading_WHOVOC_info()
        leading_WHO_dict = getattr(self, all_OR_rbd_str + '_mutations_2_WHO_label_dict')

        folder_path = self.pars_args_GISAID_data_folder + \
                      '/' + 'LeadingWHOVOC_based_1mut_' + all_OR_rbd_str
        if not os.path.exists(folder_path):
            os.makedirs(folder_path)
            dataframe_all_saved = 0
        else:
            for WHOVOC_name in leading_WHO_dict.values():
                if not os.path.exists(folder_path + '/' + WHOVOC_name + '.csv'):
                    dataframe_all_saved = 0

        if dataframe_all_saved:
            one_mut_pd_dict = {}
            for WHOVOC_name in leading_WHO_dict.values():
                one_mut_pd_dict[WHOVOC_name] = pd.read_csv(folder_path + '/' + WHOVOC_name + '.csv')
            print('LeadingWHOVOC_based_1mut_' + all_OR_rbd_str + ' with file name ' + ' '.join(leading_WHO_dict.values()) + ' exist!')
        else:
            if not hasattr(self, 'GISAID_data_MissenseMutationsIndex'):
                self.set_GISAID_data_MissenseMutationsIndex(all_OR_rbd_str=all_OR_rbd_str)
            if not hasattr(self, 'GISAID_data_SingleMutationIndex'):
                self.set_GISAID_data_SingleMutationIndex()

            if all_OR_rbd_str == 'all':
                filename_prefix = 'all_'
                position_num    = 1273
                position_ini    = 1
            elif all_OR_rbd_str == 'rbd':
                filename_prefix = 'rbd_331_531_'
                position_num    = 201
                position_ini    = 331
            else:
                raise ValueError("please set: all_OR_rbd_str = 'all' or 'rbd'")
            filename_prefix_path = folder_path + '/' + filename_prefix

            if not hasattr(self, 'alphabet'):
                self.set_attribute_constants()
            AA_length = len(self.alphabet)


            one_mut_pd_dict= {}
            for leading_mutations in leading_WHO_dict:
                # print(leading_mutations)
                if leading_mutations == 'B0B':
                    this_aa_str = self.P0DTC2[position_ini-1:position_ini+position_num-1]
                else:
                    leading_mutations_list = leading_mutations.split(',')
                    pre_i       = position_ini - 1
                    this_aa_str = ''
                    for this_leading_mutations in leading_mutations_list:
                        this_i       = int(this_leading_mutations[1:-1]) - 1
                        this_aa_str += self.P0DTC2[pre_i: this_i]
                        if self.P0DTC2[int(this_leading_mutations[1:-1]) - 1] != this_leading_mutations[0]:
                            raise ValueError("please check: 2 AAs are different, when comparing AA-sequence and mutations description ")
                        this_aa_str += this_leading_mutations[-1]
                        pre_i        = this_i + 1
                    this_aa_str += self.P0DTC2[pre_i: position_ini+position_num - 1]
                # print(this_aa_str, leading_mutations)

                one_mut_pd = pd.DataFrame( { 'position': [ num for num in range(position_ini, position_ini+position_num) for _ in range(AA_length) ] ,
                                             'wt': [ this_aa_str[i] for i in range(position_num) for _ in range(AA_length) ],
                                             'mut': list(self.alphabet * position_num)
                                             })
                one_mut_pd = one_mut_pd[one_mut_pd['wt'] != one_mut_pd['mut']]
                one_mut_pd['mutations'] = one_mut_pd['wt'] + one_mut_pd['position'].apply(str) + one_mut_pd['mut']
                one_mut_pd['wtmut'] = one_mut_pd['wt'] + one_mut_pd['mut']
                one_mut_pd['Ndis']  = one_mut_pd['wtmut'].apply(lambda x: self.AA_min_nuc_dis_dict[x])
                one_mut_pd['aa_str'] = one_mut_pd['mutations'].apply(self.compute_mut_2_aa_str, args=(this_aa_str, position_ini, ))
                one_mut_pd['mutations_whole'] = one_mut_pd['aa_str'].apply(self.compute_aa_str_2_whole_mutations, args=(self.P0DTC2[position_ini-1:position_ini+position_num-1], position_ini, ))
                one_mut_pd['mutations_single'] = one_mut_pd['position'].apply(lambda x: self.P0DTC2[x-1]) + one_mut_pd['position'].apply(str) + one_mut_pd['mut']
                one_mut_pd = one_mut_pd.merge(self.GISAID_data_MissenseMutationsIndex, how='left', left_on='mutations_whole', right_index=True)
                one_mut_pd.rename(columns={'count': 'whole_count', 'first_seen': 'whole_first_seen'}, inplace=True)
                one_mut_pd = one_mut_pd.merge(self.GISAID_data_SingleMutationIndex, how='left', left_on='mutations_single', right_index=True)
                one_mut_pd.rename(columns={'count': 'single_count', 'first_seen': 'single_first_seen'}, inplace=True)

                one_mut_pd_dict[leading_WHO_dict[leading_mutations]] = one_mut_pd


                # for i in range(one_mut_pd.shape[0]):
                #     val = one_mut_pd.iloc[i]['mutations_whole']
                #     if val in self.GISAID_data_MissenseMutationsIndex.index:
                #         print(self.GISAID_data_MissenseMutationsIndex.loc[val, 'count'])
                # from aa_str to mutations:
                # mutations_this_leading = [one_mut_pd_dict['Initial'].loc[0, 'aa_str'][i] + str(i + position_ini) + one_mut_pd_dict[leading_WHO_dict[leading_mutations]].loc[0, 'aa_str'][i] for i in range(position_num) if one_mut_pd_dict['Initial'].loc[0, 'aa_str'][i] != one_mut_pd_dict[leading_WHO_dict[leading_mutations]].loc[0, 'aa_str'][i]]
                # if len(mutations_this_leading) > 0:
                #     mutations_this_leading = ','.join(mutations_this_leading)
                # else:
                #     mutations_this_leading = 'B0B'
                # print(mutations_this_leading==leading_mutations, mutations_this_leading)

            for WHOVOC_name in leading_WHO_dict.values():
                one_mut_pd_dict[WHOVOC_name].to_csv(folder_path + '/' + WHOVOC_name + '.csv',  index=False)
        if set_attribute:
            setattr(self, all_OR_rbd_str + '_one_mut_pd_dict', one_mut_pd_dict)
        # print('aaaaaaa')

