    def get_filename(self, *, one_month_OR_two_weeks_str, all_OR_rbd_str, location_str, survival_OR_target_new_OR_history_str='survival'):
        """
        Get path of the file to be loaded
        Input:
            one_month_OR_two_weeks_str: 'one_month' or 'two_weeks': The time interval for count
            all_OR_rbd_str: 'all' or 'rbd': Consider all positions or only RBD
            location_str: ONLY can be selected from: ['Africa /', 'Asia /', 'Europe /', 'North America /', 'Oceania /', 'South America /', 'all /']
        """
        if one_month_OR_two_weeks_str == 'one_month':
            strtime_list     = (['2019-12-1'] +
                                [str(y) + '-' + str(x) + '-01' for y in range(2020, 2024) for x in range(1, 13)] +
                                ['2024-1-1'])
            strtime_2_nptime = lambda x: (int(x[:4]) - 2020) * 12 + int(x[5:7])
        elif one_month_OR_two_weeks_str == 'two_weeks':
            strtime_list     = (['2019-12-1'] + ['2019-12-15'] +
                                [str(y) + '-' + str(x) + d for y in range(2020, 2024) for x in range(1, 13) for d in ['-01', '-15']] +
                                ['2024-1-1'])
            strtime_2_nptime = lambda x: (int(x[:4]) - 2020) * 24 + int(x[5:7]) * 2 + int(int(x[-2:]) > 14)
        else:
            raise ValueError("please set: one_month_OR_two_weeks_str = 'one_month' or 'two_weeks'")
        datetime_list = [dt.strptime(x, '%Y-%m-%d') for x in strtime_list]
        load_file_num = len(strtime_list) - 1

        if all_OR_rbd_str == 'all':
            sub_folder_name   = survival_OR_target_new_OR_history_str + '_all'
            filename_prefix   = survival_OR_target_new_OR_history_str + '_all_'
        elif all_OR_rbd_str == 'rbd':
            sub_folder_name   = survival_OR_target_new_OR_history_str + '_rbd'
            filename_prefix   = survival_OR_target_new_OR_history_str + '_rbd_331_531_'
        else:
            raise ValueError("please set: all_OR_rbd_str = 'all' or 'rbd'")

        sub_sub_folder_name = 'location_' + location_str[:-2].replace(' ', '_')
        filename_suffix     = 'location_' + location_str[:-2].replace(' ', '_')  + '_dataframe_'
        folder_path         = self.pars_args_GISAID_data_folder + \
                                  '/' + one_month_OR_two_weeks_str + \
                                  '/' + sub_folder_name + \
                                  '/' + sub_sub_folder_name
        filename_prefix_path = folder_path + '/' + filename_prefix + filename_suffix

        folder_path_more_cols    = self.pars_args_GISAID_data_folder + \
                                  '/' + one_month_OR_two_weeks_str + \
                                  '/' + sub_folder_name + '_more_cols' + \
                                  '/' + sub_sub_folder_name
        filename_prefix_path_more_clos = folder_path_more_cols + '/' + filename_prefix + filename_suffix

        folder_path_figs          = self.pars_args_figs_ForGISAIDData_folder + \
                                  '/' + one_month_OR_two_weeks_str + \
                                  '/' + all_OR_rbd_str + \
                                  '/' + sub_sub_folder_name
        filename_prefix_path_figs = folder_path_figs + '/' + all_OR_rbd_str + '_location_' + location_str[:-2].replace(' ', '_') + '.pdf'

        return {'filename_prefix_path': filename_prefix_path,
                'folder_path': folder_path,
                'filename_prefix_path_more_clos': filename_prefix_path_more_clos,
                'folder_path_more_cols': folder_path_more_cols,
                'strtime_2_nptime': strtime_2_nptime,
                'load_file_num': load_file_num,
                'datetime_list': datetime_list,
                'sub_folder_name': sub_folder_name,
                'sub_sub_folder_name': sub_sub_folder_name,
                'folder_path_figs': folder_path_figs,
                'filename_prefix_path_figs': filename_prefix_path_figs
                }

