                    with open(filename_prefix_path_figs_ForLog, "w") as logs:
                        for i, x in enumerate(survival_pdlist):
                            if x.shape[0]:
                                logs.write(str(i) + ':----' + str(datetime_list[i]) + '\n' )
                                logs.write(x.index[0] + '\n')
                                if x.shape[0]>2:
                                    logs.write(x.index[1] + '\n')
                                    logs.write(x.index[2] + '\n')

                    ExtinctLastMonth_cnt_ratio_list = [[0, 0] for _ in range(len(survival_pdlist))]
                    for i, df in enumerate(survival_pdlist):
                        if df.shape[0]:
                            ExtinctLastMonth_cnt_ratio_list[i][0] = df[df['extinct_last_month'] == 1]['count'].sum()
                            ExtinctLastMonth_cnt_ratio_list[i][1] = ExtinctLastMonth_cnt_ratio_list[i][0] / df['count'].sum()

                    TargetNewOverNew_cnt_ratio_list = [[0, 0] for _ in range(len(target_new_pdlist))]
                    for i, df in enumerate(target_new_pdlist):
                        if df.shape[0]:
                            TargetNewOverNew_cnt_ratio_list[i][0] = df['count'].sum()
                            TargetNewOverNew_cnt_ratio_list[i][1] = TargetNewOverNew_cnt_ratio_list[i][0] / ExtinctLastMonth_cnt_ratio_list[i][0]
                    xmax = max( [x[0] for x in ExtinctLastMonth_cnt_ratio_list] )

                    fig, axs = plt.subplots(2, 2, figsize=(8*2, 6*2))
                    axs[0, 0].plot(datetime_list[:-1], [x[1] * xmax for x in TargetNewOverNew_cnt_ratio_list],  label='1 RNA reachable ratio(over new)')
                    axs[0, 0].plot(datetime_list[:-1], [x[0] for x in ExtinctLastMonth_cnt_ratio_list],  label='New count')
                    axs[0, 0].legend()

                    MutCnt_mean_std_list = [[0, 0] for _ in range(len(target_new_pdlist))]
                    All_cnt_list         = [ 0 ] * len(target_new_pdlist)
                    for i, df in enumerate(survival_pdlist):
                        if df.shape[0]:
                            MutCnt_mean_std_list[i][0] = np.average( np.array(df['mut_cnt']), weights=np.array(df['count']))
                            MutCnt_mean_std_list[i][1] = np.cov(np.array(df['mut_cnt']), fweights=np.array(df['count']))

                    axs[0, 1].plot(datetime_list[:-1], [x[1]  for x in MutCnt_mean_std_list],  label='Mut-count mean')
                    axs[0, 1].plot(datetime_list[:-1], [x[0]  for x in MutCnt_mean_std_list],  label='Mut-count std')
                    axs[0, 1].legend()

                    All_cnt_list         = [ 0 ] * len(target_new_pdlist)
                    for i, df in enumerate(survival_pdlist):
                        if df.shape[0]:
                            All_cnt_list[i]            = df['count'].sum()

                    axs[1, 1].plot(datetime_list[:-1], [x for x in All_cnt_list],  label='All counts')
                    axs[1, 1].plot(datetime_list[:-1], [x[0] * 5 for x in ExtinctLastMonth_cnt_ratio_list],  label='New counts * 5')
                    axs[1, 1].legend()

                    PossibleTargetNewOverTargetNew_cnt_ratio_list = [[0, 0, 0] for _ in range(len(target_new_pdlist))]
                    for i, df in enumerate(target_new_pdlist):
                        if df.shape[0]:
                            PossibleTargetNewOverTargetNew_cnt_ratio_list[i][0] = df[df['father_last_month_max_ratio'] >= 0.05 ]['count'].sum()
                            PossibleTargetNewOverTargetNew_cnt_ratio_list[i][1] = PossibleTargetNewOverTargetNew_cnt_ratio_list[i][0] / TargetNewOverNew_cnt_ratio_list[i][0]
                            PossibleTargetNewOverTargetNew_cnt_ratio_list[i][2] = sum(df['father_last_month_max_ratio'] >= 0.01) / sum(df['extinct_last_month'] == 1)
                    ymax = max([x[0] for x in PossibleTargetNewOverTargetNew_cnt_ratio_list])

                    axs[1, 0].plot(datetime_list[:-1], [x[0] for x in PossibleTargetNewOverTargetNew_cnt_ratio_list],  label='Possible-generating count (in our method)')
                    axs[1, 0].plot(datetime_list[:-1], [x[1] * ymax  for x in PossibleTargetNewOverTargetNew_cnt_ratio_list],  label='Possible-generating count over reachable 1 RNA')
                    axs[1, 0].plot(datetime_list[:-1], [x[2] * ymax for x in PossibleTargetNewOverTargetNew_cnt_ratio_list],   label='Possible-generating CASE-num count over reachable 1 RNA')
                    axs[1, 0].legend()

                    plt.tight_layout(rect=[0, 0, 1, 0.95])
                    plt.suptitle(one_month_OR_two_weeks_str + '_' + all_OR_rbd_str + '_location_' + location_str[:-2].replace(' ', '_'))
                    plt.savefig(filename_prefix_path_figs)
                    plt.close()
